CREATE TYPE public.app_role AS ENUM ('owner');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE FUNCTION public.assign_portfolio_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'filmabent@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'owner') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.assign_portfolio_owner() FROM PUBLIC;
CREATE TRIGGER portfolio_owner_on_auth AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_portfolio_owner();
CREATE TABLE public.portfolio_categories (slug text PRIMARY KEY CHECK (slug IN ('narrative','weddings','music','imagefilms')), featured_url text NOT NULL DEFAULT '', gallery_urls jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(gallery_urls) = 'array'), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.portfolio_categories TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.portfolio_categories TO authenticated;
GRANT ALL ON public.portfolio_categories TO service_role;
ALTER TABLE public.portfolio_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public portfolio" ON public.portfolio_categories FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Owner inserts portfolio" ON public.portfolio_categories FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'owner'));
CREATE POLICY "Owner updates portfolio" ON public.portfolio_categories FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'owner')) WITH CHECK (public.has_role(auth.uid(),'owner'));
CREATE POLICY "Owner deletes portfolio" ON public.portfolio_categories FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'owner'));